  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "A shop owner asks: \\"How much did we sell between day 12 and day 40?\\" Asking 10,000 such questions one by one is slow. Preparing once makes every answer instant."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## The idea\\n\\nAn array gives you O(1) access by index, so most array problems are about **not repeating work**. The most useful trick is the **prefix sum**: `prefix[i]` is the sum of the first `i` elements.\\n\\nThen the sum of any range `nums[l..r]` is `prefix[r + 1] - prefix[l]` — two lookups, no loop.\\n\\n## Template\\n\\n```python\\ndef build_prefix(nums):\\n    prefix = [0]\\n    for x in nums:\\n        prefix.append(prefix[-1] + x)\\n    return prefix\\n\\ndef range_sum(prefix, l, r):      # inclusive\\n    return prefix[r + 1] - prefix[l]\\n```\\n\\n## Where it shows up\\n- Many range-sum questions after a single preparation pass.\\n- **Subarray sum equals k**: a subarray ends at `j` with sum `k` exactly when some earlier prefix equals `prefix[j] - k`. Store prefix counts in a hash map.\\n- Running best/worst values (Kadane''s algorithm, best time to buy and sell).\\n\\n## Watch out for\\n- Off-by-one errors: the prefix array has `n + 1` entries.\\n- Negative numbers break \\"grow the window\\" thinking, but prefix sums still work.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Check your understanding', E'{"quiz_questions": [{"question": "What is the sum of nums[l..r] using a prefix array of length n + 1?", "options": ["prefix[r + 1] - prefix[l]", "prefix[r] - prefix[l]", "prefix[r] + prefix[l]", "prefix[r + 1] + prefix[l]"], "correctAnswer": "prefix[r + 1] - prefix[l]", "explanation": "prefix[i] holds the sum of the first i elements, so subtracting the prefix before l from the prefix through r leaves exactly nums[l..r]."}, {"question": "After a one-time O(n) preparation, how long does each range-sum query take?", "options": ["O(1)", "O(n)", "O(log n)", "O(n^2)"], "correctAnswer": "O(1)", "explanation": "Each query is two array lookups and a subtraction."}, {"question": "Why does a prefix-sum + hash-map approach handle arrays with negative numbers?", "options": ["It never shrinks a window; it only compares prefix values", "It sorts the array first", "It ignores negative values", "It only works for positive values"], "correctAnswer": "It never shrinks a window; it only compares prefix values", "explanation": "Window-shrinking logic needs positive numbers; comparing prefix values does not."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Practice', E'{"task_prompt": "Open Practice and solve these problems, which all use this pattern: Maximum Subarray Sum; Product of Array Except Self; Subarray Sum Equals K. Write down, in one sentence, why the pattern fits each one."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "Two friends type their names in a hurry. Are the two scrambles the same letters? Counting beats comparing."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## The idea\\n\\nA string is an array of characters, so every array idea applies — plus one very common tool: a **frequency table** (a dictionary or a 26-slot array) that counts how often each character appears.\\n\\nTwo strings are anagrams exactly when their frequency tables are equal. A string can be built from another when the available counts cover the needed counts.\\n\\n## Template\\n\\n```python\\nfrom collections import Counter\\n\\ndef is_anagram(a, b):\\n    return Counter(a) == Counter(b)\\n\\ndef can_build(note, source):\\n    need, have = Counter(note), Counter(source)\\n    return all(have[c] >= n for c, n in need.items())\\n```\\n\\n## Habits that save you\\n- Strings are immutable in most languages. Building a result by `+=` in a loop can be O(n^2); collect pieces in a list and join once.\\n- Decide early if case, spaces and punctuation matter.\\n- For palindromes, compare from both ends with two pointers instead of reversing when memory matters.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Check your understanding', E'{"quiz_questions": [{"question": "Two strings are anagrams exactly when…", "options": ["their character counts are equal", "they have the same length", "they share the first letter", "one is a substring of the other"], "correctAnswer": "their character counts are equal", "explanation": "Anagrams use the same letters the same number of times, in any order."}, {"question": "Why is building a long string with += inside a loop often slow?", "options": ["Each += may copy the whole string", "Strings cannot be changed", "Loops are slow in general", "It uses recursion"], "correctAnswer": "Each += may copy the whole string", "explanation": "Immutable strings are copied on each concatenation, making the loop O(n^2) in the worst case."}, {"question": "How many slots does a frequency array need for lowercase English letters?", "options": ["26", "10", "52", "128"], "correctAnswer": "26", "explanation": "One slot per letter a to z."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Practice', E'{"task_prompt": "Open Practice and solve these problems, which all use this pattern: Valid Palindrome; First Unique Character; Ransom Note. Write down, in one sentence, why the pattern fits each one."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "A receptionist greets thousands of visitors a day and instantly knows who has been here before. A hash map is that memory."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## The idea\\n\\nA hash map (dictionary) or hash set gives **average O(1)** insert and lookup. Many O(n^2) \\"compare every pair\\" solutions become O(n) once you ask: *what do I need to remember so I can answer in one step?*\\n\\n## Two-sum, the classic\\n\\nFor each number `x`, you need to know whether `target - x` has appeared before. Remember each number''s index as you go.\\n\\n```python\\ndef two_sum(nums, target):\\n    seen = {}                      # value -> index\\n    for i, x in enumerate(nums):\\n        if target - x in seen:\\n            return [seen[target - x], i]\\n        seen[x] = i\\n    return []\\n```\\n\\n## Patterns\\n- **Seen set** — duplicates, first repeat, cycle detection.\\n- **Counter** — frequencies, majority, top-k.\\n- **Value -> index** — pair finding, \\"last seen position\\" for windows.\\n- **Canonical key** — group items by a key (sorted letters for anagrams).\\n\\n## Costs\\nLookups are O(1) on average, but memory is O(n). Keys must be hashable and stable (use tuples, not lists).\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Check your understanding', E'{"quiz_questions": [{"question": "What is the average cost of a lookup in a hash map?", "options": ["O(1)", "O(n)", "O(log n)", "O(n log n)"], "correctAnswer": "O(1)", "explanation": "Hashing jumps straight to the bucket, so lookups are constant time on average."}, {"question": "To find a pair that sums to a target in one pass, what do you store?", "options": ["Each number seen, with its index", "The sorted array", "Only the largest number", "The sum of all numbers"], "correctAnswer": "Each number seen, with its index", "explanation": "For every new number you check whether the needed partner was seen already."}, {"question": "Which of these cannot be used as a dictionary key in Python?", "options": ["A list", "A tuple of numbers", "A string", "An integer"], "correctAnswer": "A list", "explanation": "Lists are mutable and unhashable; tuples of hashables are fine."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Practice', E'{"task_prompt": "Open Practice and solve these problems, which all use this pattern: Isomorphic Strings; Subarray Sum Equals K; Find All Duplicates. Write down, in one sentence, why the pattern fits each one."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "Two people start at opposite ends of a corridor, each walking inward, deciding who steps based on what they see. They meet in the middle having checked everything that mattered."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## The idea\\n\\nUse two indexes that move through the data according to a rule. It works when the data is **sorted** or has a structure that tells you *which pointer to move*.\\n\\n## Opposite ends: sorted two-sum\\n\\n```python\\ndef two_sum_sorted(nums, target):\\n    l, r = 0, len(nums) - 1\\n    while l < r:\\n        s = nums[l] + nums[r]\\n        if s == target:\\n            return [l, r]\\n        if s < target:\\n            l += 1          # need a bigger sum\\n        else:\\n            r -= 1          # need a smaller sum\\n    return []\\n```\\n\\n## Same direction (slow and fast)\\nA write pointer builds the answer in place (remove duplicates, move zeroes) while a read pointer scans.\\n\\n## Why it is correct\\nAt each step you can *prove* that moving one pointer discards only candidates that cannot be the answer. State that argument out loud in an interview — it is what interviewers listen for.\\n\\n## Typical problems\\nPair sums, 3Sum (fix one, two-pointer the rest), container with most water, palindromes, merging sorted arrays, squaring sorted arrays.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Check your understanding', E'{"quiz_questions": [{"question": "When the pair sum is smaller than the target in a sorted array, which pointer moves?", "options": ["The left pointer moves right", "The right pointer moves left", "Both move", "Neither; stop"], "correctAnswer": "The left pointer moves right", "explanation": "A larger sum needs a larger left value, and the array is sorted ascending."}, {"question": "What is the time complexity of the sorted two-pointer pair search?", "options": ["O(n)", "O(n^2)", "O(log n)", "O(1)"], "correctAnswer": "O(n)", "explanation": "Each pointer moves at most n steps in total."}, {"question": "3Sum is usually solved by…", "options": ["Sorting, fixing one number, and running two pointers on the rest", "Trying all pairs with a hash map only", "Binary search on the answer", "Recursion on every subset"], "correctAnswer": "Sorting, fixing one number, and running two pointers on the rest", "explanation": "After sorting, each fixed value reduces the problem to a two-pointer sweep, giving O(n^2)."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Practice', E'{"task_prompt": "Open Practice and solve these problems, which all use this pattern: Two Sum in a Sorted Array; 3Sum; Container With Most Water; Squares of a Sorted Array. Write down, in one sentence, why the pattern fits each one."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "A camera looks at a street through a frame that slides along it. Instead of re-examining the whole frame each time, you only update what enters and what leaves."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## The idea\\n\\nWhen a question is about a **contiguous** part of an array or string, keep a *window* `[l, r]` and update it incrementally as `r` moves right. Shrink from the left when the window breaks a rule.\\n\\n## Fixed-size window\\nAdd the entering element, remove the leaving one.\\n\\n```python\\ndef max_window_sum(nums, k):\\n    s = sum(nums[:k])\\n    best = s\\n    for i in range(k, len(nums)):\\n        s += nums[i] - nums[i - k]\\n        best = max(best, s)\\n    return best\\n```\\n\\n## Variable-size window\\nGrow `r`; while the window is invalid, advance `l`.\\n\\n```python\\ndef longest_unique(s):\\n    last, start, best = {}, 0, 0\\n    for i, ch in enumerate(s):\\n        if ch in last and last[ch] >= start:\\n            start = last[ch] + 1\\n        last[ch] = i\\n        best = max(best, i - start + 1)\\n    return best\\n```\\n\\n## When it works\\nThe rule must be *monotone*: removing from the left never makes an invalid window \\"more invalid\\". With negative numbers a sum rule is not monotone — use prefix sums instead.\\n\\nEvery index enters and leaves the window at most once, so the cost is O(n).\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Check your understanding', E'{"quiz_questions": [{"question": "In a fixed-size window, what changes when it slides by one step?", "options": ["One element enters and one leaves", "The whole window is recomputed", "The window size doubles", "Nothing"], "correctAnswer": "One element enters and one leaves", "explanation": "Updating the running value by the difference avoids recomputing."}, {"question": "Why does the sliding window run in O(n)?", "options": ["Each index enters and leaves the window at most once", "It sorts the array first", "It uses binary search", "It stops after k steps"], "correctAnswer": "Each index enters and leaves the window at most once", "explanation": "Both pointers only move forward."}, {"question": "A variable window for \\"sum at least target\\" needs the numbers to be…", "options": ["Positive", "Negative", "Sorted descending", "Distinct"], "correctAnswer": "Positive", "explanation": "With positives, shrinking always lowers the sum, which makes the rule monotone."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Practice', E'{"task_prompt": "Open Practice and solve these problems, which all use this pattern: Maximum Sum of a Window; Minimum Size Subarray Sum; Longest Substring Without Repeating Characters; Permutation in String; Sliding Window Maximum. Write down, in one sentence, why the pattern fits each one."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "A pile of plates: you can only touch the top one. That restriction is exactly what makes nested structure easy to check."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## The idea\\n\\nA stack is last-in, first-out. Use it when the **most recent unresolved thing** is the one you must deal with first: matching brackets, undo, nested expressions, evaluating postfix notation.\\n\\n## Matching brackets\\n\\n```python\\ndef valid(s):\\n    pair = {'')'': ''('', '']'': ''['', ''}'': ''{''}\\n    st = []\\n    for c in s:\\n        if c in pair:\\n            if not st or st.pop() != pair[c]:\\n                return False\\n        else:\\n            st.append(c)\\n    return not st\\n```\\n\\n## Monotonic stack\\nKeep the stack sorted (for example decreasing). When a new value breaks the order, pop and **resolve** the popped items — they just found their \\"next greater\\" element.\\n\\n```python\\ndef next_greater(nums):\\n    out, st = [-1] * len(nums), []\\n    for i, x in enumerate(nums):\\n        while st and nums[st[-1]] < x:\\n            out[st.pop()] = x\\n        st.append(i)\\n    return out\\n```\\n\\nEach index is pushed once and popped once, so the whole pass is O(n) even though there is a loop inside a loop.\\n\\n## Problems that use it\\nDaily temperatures, next greater element, largest rectangle in a histogram, evaluate reverse Polish notation.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Check your understanding', E'{"quiz_questions": [{"question": "Which structure fits \\"match the most recent unclosed bracket\\"?", "options": ["Stack", "Queue", "Hash map", "Binary tree"], "correctAnswer": "Stack", "explanation": "The latest opening bracket must close first: last in, first out."}, {"question": "Why is a monotonic stack pass O(n) despite the nested loop?", "options": ["Each element is pushed and popped at most once", "The inner loop never runs", "It sorts the input", "It uses recursion"], "correctAnswer": "Each element is pushed and popped at most once", "explanation": "Total pushes and pops are at most 2n."}, {"question": "In \\"next greater element\\", when is an index popped?", "options": ["When a larger value arrives", "When a smaller value arrives", "At the end only", "Never"], "correctAnswer": "When a larger value arrives", "explanation": "The arriving value is the first greater one to the right of every smaller value on the stack."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Practice', E'{"task_prompt": "Open Practice and solve these problems, which all use this pattern: Valid Brackets; Daily Temperatures; Next Greater Element; Evaluate Reverse Polish Notation; Largest Rectangle in Histogram. Write down, in one sentence, why the pattern fits each one."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "Guess a number between 1 and 1,000,000. With \\"higher or lower\\" hints you need at most 20 guesses. That is the power of halving."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## The idea\\n\\nWhenever you can ask a yes/no question whose answer flips **once** along an ordered range, you can binary search it: look at the middle, discard half.\\n\\n## Classic search\\n\\n```python\\ndef search(nums, target):\\n    l, r = 0, len(nums) - 1\\n    while l <= r:\\n        m = (l + r) // 2\\n        if nums[m] == target:\\n            return m\\n        if nums[m] < target:\\n            l = m + 1\\n        else:\\n            r = m - 1\\n    return -1\\n```\\n\\n## Binary search on the answer\\nMany problems ask for a *minimum value that works* (eating speed, ship capacity). If \\"works\\" is monotone — once a value works, every larger one does — search the value range and test each middle with a simple check.\\n\\n```python\\ndef min_speed(piles, h):\\n    l, r = 1, max(piles)\\n    while l < r:\\n        m = (l + r) // 2\\n        if sum((p + m - 1) // m for p in piles) <= h:\\n            r = m              # m works; try smaller\\n        else:\\n            l = m + 1\\n    return l\\n```\\n\\n## Pitfalls\\n- Infinite loops from `l = m` without a rounding fix: pick the **half-open** style (`while l < r`) or round the middle up.\\n- Decide whether you want the *first* index meeting a condition (lower bound) or the *last*.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Check your understanding', E'{"quiz_questions": [{"question": "How many steps does binary search need on one million sorted items (about)?", "options": ["20", "1,000", "500,000", "1,000,000"], "correctAnswer": "20", "explanation": "log2(1,000,000) is about 20."}, {"question": "\\"Binary search on the answer\\" requires that the check function is…", "options": ["Monotone: once true, it stays true", "Random", "Recursive", "Always true"], "correctAnswer": "Monotone: once true, it stays true", "explanation": "Only then does the middle value tell you which half to discard."}, {"question": "Which loop condition pairs with \\"r = m\\" and \\"l = m + 1\\"?", "options": ["while l < r", "while l <= r", "while l > r", "while True with no update"], "correctAnswer": "while l < r", "explanation": "The half-open range shrinks every step and ends with l == r as the answer."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Practice', E'{"task_prompt": "Open Practice and solve these problems, which all use this pattern: Binary Search; Search Insert Position; Search in Rotated Sorted Array; First and Last Position of a Value; Eating Speed; Capacity to Ship Packages. Write down, in one sentence, why the pattern fits each one."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "A receptionist has a pile of bookings with start and end times. The first thing she does is sort them by start time — suddenly overlaps are neighbours."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## The idea\\n\\nSorting costs O(n log n) but often turns a messy problem into a linear scan. Ask: *if this were sorted, what would become easy?*\\n\\n## Merge intervals\\n\\n```python\\ndef merge(intervals):\\n    out = []\\n    for s, e in sorted(intervals):\\n        if out and s <= out[-1][1]:\\n            out[-1][1] = max(out[-1][1], e)\\n        else:\\n            out.append([s, e])\\n    return out\\n```\\n\\n## Which order to sort by?\\n- **Merge overlapping intervals** — by start.\\n- **Keep the most non-overlapping intervals** — by *end* (finishing early leaves the most room).\\n- **Meeting rooms** — turn each interval into +1 / -1 events and sort the events.\\n\\n## Counting sort\\nWhen values are in a small range (like 0, 1, 2 for colours) you can sort in O(n) with counts or the Dutch national flag method.\\n\\nPython''s `sorted` is stable, so you can sort by several keys by sorting on the least important key first, or by using a tuple key.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Check your understanding', E'{"quiz_questions": [{"question": "To merge overlapping intervals you first sort by…", "options": ["Start time", "Length", "End time only", "Nothing; no sort is needed"], "correctAnswer": "Start time", "explanation": "After sorting by start, any interval that overlaps the previous one starts inside it."}, {"question": "To keep the maximum number of non-overlapping intervals, sort by…", "options": ["End time", "Start time", "Length, longest first", "Random order"], "correctAnswer": "End time", "explanation": "Finishing earliest leaves the most room for the remaining intervals."}, {"question": "What does sorting cost in general?", "options": ["O(n log n)", "O(n)", "O(n^2) always", "O(1)"], "correctAnswer": "O(n log n)", "explanation": "Comparison sorts have an n log n lower bound."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Practice', E'{"task_prompt": "Open Practice and solve these problems, which all use this pattern: Merge Intervals; Non-overlapping Intervals; Meeting Rooms; Sort Colors. Write down, in one sentence, why the pattern fits each one."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "At a buffet with a time limit you grab what gives the most value per second now. Sometimes the best local move is also the best overall move."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## The idea\\n\\nA greedy algorithm makes the best-looking choice at each step and never looks back. It is fast and simple, but it is only correct when you can *argue* that the local choice never hurts the final answer.\\n\\n## A proof pattern: \\"stay ahead\\" or \\"exchange\\"\\n- **Stay ahead**: after each step, greedy is at least as good as any other strategy. *Jump game*: the furthest reachable index is only ever extended.\\n- **Exchange**: swap any optimal solution''s first choice for greedy''s and show it does not get worse. *Activity selection*: picking the earliest-finishing interval first.\\n\\n```python\\ndef can_jump(nums):\\n    reach = 0\\n    for i, x in enumerate(nums):\\n        if i > reach:\\n            return False\\n        reach = max(reach, i + x)\\n    return True\\n```\\n\\n## When greedy fails\\nCoin change with coins {1, 3, 4} and amount 6: greedy takes 4 + 1 + 1 (3 coins) but 3 + 3 (2 coins) is better. When local choices interact, use dynamic programming.\\n\\n## Checklist\\n1. Can I state the greedy rule in one sentence?\\n2. Can I explain why it never hurts?\\n3. Can I find a small counter-example? If yes, use DP.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Check your understanding', E'{"quiz_questions": [{"question": "Greedy is only correct when…", "options": ["The local choice can never hurt the final answer", "The input is sorted", "The array is small", "It uses recursion"], "correctAnswer": "The local choice can never hurt the final answer", "explanation": "Without that guarantee, greedy can commit to a choice that blocks the optimum."}, {"question": "With coins {1, 3, 4} and amount 6, what does the greedy \\"largest coin first\\" give?", "options": ["3 coins (4+1+1)", "2 coins (3+3)", "1 coin", "It cannot make 6"], "correctAnswer": "3 coins (4+1+1)", "explanation": "Greedy takes 4, then 1, then 1; but 3+3 uses only 2 coins, so greedy is wrong here."}, {"question": "In the jump game, what does the scan keep track of?", "options": ["The furthest reachable index", "The smallest jump", "The number of jumps", "The sum of the array"], "correctAnswer": "The furthest reachable index", "explanation": "If the current index is beyond the furthest reach you are stuck."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Practice', E'{"task_prompt": "Open Practice and solve these problems, which all use this pattern: Jump Game; Gas Station; Non-overlapping Intervals. Write down, in one sentence, why the pattern fits each one."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "You are in a maze with a ball of thread. At every junction you try a path; at a dead end you pull the thread back and try the next. That is backtracking."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## The idea\\n\\nBacktracking explores all candidate solutions by **choose -> explore -> un-choose**. It is a depth-first search over a tree of decisions, pruning branches that cannot work.\\n\\n## Template\\n\\n```python\\ndef subsets(nums):\\n    out, cur = [], []\\n    def go(i):\\n        if i == len(nums):\\n            out.append(cur[:])      # copy the current choice\\n            return\\n        go(i + 1)                   # skip nums[i]\\n        cur.append(nums[i])         # choose nums[i]\\n        go(i + 1)\\n        cur.pop()                   # un-choose\\n    go(0)\\n    return out\\n```\\n\\n## Anatomy\\n1. **State**: what you have chosen so far.\\n2. **Choices**: what you may add next.\\n3. **Goal**: when to record a result.\\n4. **Pruning**: when to stop early (remaining total negative, bracket count exceeded).\\n\\n## Counting the work\\nSubsets: 2^n. Permutations: n!. Combination sum: bounded by the target. Always estimate this before coding so you know whether it will be fast enough (n up to about 20 for 2^n).\\n\\n## Common mistakes\\n- Appending `cur` instead of a copy `cur[:]` — every result then changes later.\\n- Forgetting to undo the choice.\\n- Generating duplicates: move forward through the candidates instead of restarting from the beginning.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Check your understanding', E'{"quiz_questions": [{"question": "What are the three moves of backtracking?", "options": ["Choose, explore, un-choose", "Sort, search, return", "Split, merge, sort", "Push, pop, peek"], "correctAnswer": "Choose, explore, un-choose", "explanation": "You make a choice, recurse, then undo it to try the next option."}, {"question": "How many subsets does a set of 10 distinct numbers have?", "options": ["1024", "100", "3,628,800", "20"], "correctAnswer": "1024", "explanation": "2^10 = 1024."}, {"question": "Why do you append a COPY of the current list to the results?", "options": ["Otherwise later changes alter stored results", "Copies run faster", "Lists cannot be appended", "To save memory"], "correctAnswer": "Otherwise later changes alter stored results", "explanation": "The same list object is modified as the search continues, so a stored reference would change too."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Practice', E'{"task_prompt": "Open Practice and solve these problems, which all use this pattern: Subsets; Permutations; Combination Sum; Generate Parentheses. Write down, in one sentence, why the pattern fits each one."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "Climbing a staircase, you realise the number of ways to reach step 10 depends on steps 9 and 8 — which you already counted. Never solve the same sub-problem twice."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## The idea\\n\\nDynamic programming (DP) solves a problem by solving smaller **overlapping** sub-problems once and reusing the answers.\\n\\n## A reliable recipe\\n1. **State**: what do I need to know to describe a sub-problem? (`dp[i]` = best answer for the first `i` items)\\n2. **Transition**: how does a state come from smaller states?\\n3. **Base case**: what is trivially known?\\n4. **Order**: fill smaller states first (or use memoised recursion).\\n5. **Answer**: which state holds it?\\n\\n## Example: coin change (fewest coins)\\n\\n```python\\ndef coin_change(coins, amount):\\n    INF = amount + 1\\n    dp = [0] + [INF] * amount\\n    for a in range(1, amount + 1):\\n        for c in coins:\\n            if c <= a:\\n                dp[a] = min(dp[a], dp[a - c] + 1)\\n    return dp[amount] if dp[amount] != INF else -1\\n```\\n\\n## Families you will meet\\n- **1-D line**: climbing stairs, house robber, longest increasing subsequence.\\n- **Knapsack**: subset sum, partition, 0/1 knapsack (loop capacity downward so an item is used once).\\n- **Two strings**: edit distance, longest common subsequence — a table indexed by prefixes of both.\\n- **Grid**: unique paths, minimum path sum.\\n\\n## Space optimisation\\nIf `dp[i]` only needs the previous row or the previous two values, keep only those.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Check your understanding', E'{"quiz_questions": [{"question": "What makes a problem suitable for dynamic programming?", "options": ["Overlapping sub-problems with optimal substructure", "A sorted input", "Only positive numbers", "A graph input"], "correctAnswer": "Overlapping sub-problems with optimal substructure", "explanation": "The same smaller problems recur, and the best answer is built from best sub-answers."}, {"question": "In 0/1 knapsack with a 1-D array, why loop the capacity downward?", "options": ["So each item is used at most once", "To make it faster", "To allow repeated items", "Because arrays are reversed"], "correctAnswer": "So each item is used at most once", "explanation": "Going downward means dp[c - w] still holds the value from before this item."}, {"question": "The first thing to define in a DP solution is…", "options": ["The state", "The loop order", "The language", "The input size"], "correctAnswer": "The state", "explanation": "Everything else (transition, base case, order) follows from what a state means."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Practice', E'{"task_prompt": "Open Practice and solve these problems, which all use this pattern: Climbing Stairs; House Robber; Coin Change; Longest Increasing Subsequence; Edit Distance; Longest Common Subsequence; 0/1 Knapsack. Write down, in one sentence, why the pattern fits each one."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "A treasure map is just a grid. Where you can move next depends on four neighbours — and a few tricks keep your indexing from tying itself in knots."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## The idea\\n\\nA matrix is an array of arrays. Most problems are one of:\\n- **Traversal** in a special order (spiral, diagonal).\\n- **Transformation** (rotate, transpose, set zeroes).\\n- **Search** (sorted matrix as a flat array).\\n- **Graph** disguised as a grid (islands, shortest path).\\n\\n## Neighbours\\n```python\\nDIRS = [(1, 0), (-1, 0), (0, 1), (0, -1)]\\n\\ndef neighbours(r, c, R, C):\\n    for dr, dc in DIRS:\\n        nr, nc = r + dr, c + dc\\n        if 0 <= nr < R and 0 <= nc < C:\\n            yield nr, nc\\n```\\n\\n## Rotate 90 degrees clockwise\\nReverse the order of the rows, then transpose:\\n\\n```python\\ndef rotate(matrix):\\n    return [list(row) for row in zip(*matrix[::-1])]\\n```\\n\\n## Flat index trick\\nFor a matrix with `C` columns, flat index `k` is cell `(k // C, k % C)`. A sorted-rows matrix where each row starts above the previous row''s end can be binary searched as if it were one long array.\\n\\n## Checklist\\n- Check for empty grids and single rows/columns.\\n- Do not modify the grid while scanning unless you mean to — record changes first.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Check your understanding', E'{"quiz_questions": [{"question": "For a matrix with C columns, which cell does flat index k refer to?", "options": ["(k // C, k % C)", "(k % C, k // C)", "(k * C, k)", "(k - C, k + C)"], "correctAnswer": "(k // C, k % C)", "explanation": "Integer division gives the row, remainder gives the column."}, {"question": "A 90-degree clockwise rotation equals…", "options": ["Reverse the rows, then transpose", "Transpose only", "Reverse each row only", "Sort each row"], "correctAnswer": "Reverse the rows, then transpose", "explanation": "Reversing the row order and transposing maps the first row to the last column."}, {"question": "Why record zero positions before zeroing a matrix?", "options": ["Newly created zeros would cause extra rows/columns to be zeroed", "It is faster", "Zeros cannot be overwritten", "To sort the matrix"], "correctAnswer": "Newly created zeros would cause extra rows/columns to be zeroed", "explanation": "Changing as you scan makes new zeros look original."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Practice', E'{"task_prompt": "Open Practice and solve these problems, which all use this pattern: Rotate Image; Spiral Matrix; Set Matrix Zeroes; Search a Sorted Matrix. Write down, in one sentence, why the pattern fits each one."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "Cities and roads, courses and prerequisites, friends and follows — all are graphs. Once you see the graph, three tools solve most questions."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## The idea\\n\\nA graph is nodes and edges. Grids are graphs too (each cell is a node with up to four neighbours).\\n\\n## Three tools\\n- **DFS** (stack/recursion): explore everything reachable. Counting connected components, flood fill, cycle detection.\\n- **BFS** (queue): explore level by level. The first time BFS reaches a node is by a **shortest path** when every edge costs the same.\\n- **Topological sort** (Kahn''s algorithm): order tasks by prerequisites; if you cannot place everything there is a cycle.\\n\\n```python\\nfrom collections import deque\\n\\ndef can_finish(n, prerequisites):\\n    adj = [[] for _ in range(n)]\\n    indeg = [0] * n\\n    for a, b in prerequisites:          # take b before a\\n        adj[b].append(a)\\n        indeg[a] += 1\\n    q = deque(i for i in range(n) if indeg[i] == 0)\\n    done = 0\\n    while q:\\n        u = q.popleft()\\n        done += 1\\n        for v in adj[u]:\\n            indeg[v] -= 1\\n            if indeg[v] == 0:\\n                q.append(v)\\n    return done == n\\n```\\n\\n## Multi-source BFS\\nStart the queue with *several* sources (all rotten oranges) and expand together — each level is one time step.\\n\\n## Always keep a visited set\\nWithout it a cycle makes the search run forever. Mark nodes visited when you **enqueue** them, not when you dequeue them.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Check your understanding', E'{"quiz_questions": [{"question": "Which traversal finds shortest paths in an unweighted graph?", "options": ["BFS", "DFS", "Binary search", "Sorting"], "correctAnswer": "BFS", "explanation": "BFS reaches nodes in order of increasing distance."}, {"question": "How does topological sorting reveal a cycle?", "options": ["Not every node can be removed", "The queue overflows", "A node has two parents", "It cannot"], "correctAnswer": "Not every node can be removed", "explanation": "Nodes in a cycle always have an unmet prerequisite, so they never reach in-degree zero."}, {"question": "When should a node be marked visited in BFS?", "options": ["When it is enqueued", "When it is dequeued", "Never", "After the whole BFS"], "correctAnswer": "When it is enqueued", "explanation": "Marking early prevents the same node from being queued several times."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Practice', E'{"task_prompt": "Open Practice and solve these problems, which all use this pattern: Number of Islands; Course Schedule; Rotting Oranges; Shortest Path in a Binary Matrix. Write down, in one sentence, why the pattern fits each one."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "A programmer sees the number 16 and thinks \\"10000\\". Seeing numbers as bits opens up one-line answers to problems that look hard."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## Bit basics\\n- `x & (x - 1)` clears the lowest set bit. So `x & (x - 1) == 0` for positive `x` means **power of two**; repeating it **counts set bits**.\\n- `x ^ x = 0` and `x ^ 0 = x`, so XOR-ing a list cancels pairs: the **single number** survives.\\n- `x >> 1` halves; `i >> 1` has the same set bits as `i` without its last bit, which gives `bits[i] = bits[i >> 1] + (i & 1)`.\\n\\n```python\\ndef popcount(n):\\n    c = 0\\n    while n:\\n        n &= n - 1\\n        c += 1\\n    return c\\n```\\n\\n## Number theory staples\\n- **GCD** by Euclid: `gcd(a, b) = gcd(b, a % b)`.\\n- **Sieve of Eratosthenes**: cross out multiples of each prime, O(n log log n).\\n- **Modular arithmetic**: remainders of powers repeat in a cycle; use `pow(b, e, m)`.\\n- **Factorial trailing zeros**: count factors of 5: n/5 + n/25 + ...\\n\\n```python\\ndef gcd(a, b):\\n    while b:\\n        a, b = b, a % b\\n    return a\\n```\\n\\n## Careful with\\nInteger overflow in languages with fixed-size integers (use 64-bit or modular reduction), and negative numbers with `%` and shifts.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Check your understanding', E'{"quiz_questions": [{"question": "What does x & (x - 1) do?", "options": ["Clears the lowest set bit", "Sets the lowest bit", "Doubles x", "Negates x"], "correctAnswer": "Clears the lowest set bit", "explanation": "Subtracting 1 flips the lowest set bit and the zeros below it, so the AND removes that bit."}, {"question": "XOR-ing every element of a list where each value appears twice except one gives…", "options": ["The value that appears once", "Zero", "The sum", "The largest value"], "correctAnswer": "The value that appears once", "explanation": "Equal values cancel out under XOR."}, {"question": "Euclid''s algorithm computes…", "options": ["The greatest common divisor", "The least common multiple directly", "Prime numbers", "Powers of two"], "correctAnswer": "The greatest common divisor", "explanation": "It repeatedly replaces (a, b) by (b, a mod b)."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Practice', E'{"task_prompt": "Open Practice and solve these problems, which all use this pattern: Power of Two; Number of 1 Bits; Single Number; Count Primes; Greatest Common Divisor. Write down, in one sentence, why the pattern fits each one."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "Your code works on 10 inputs but the interviewer asks about 10 million. Estimating cost before you write code is the skill that separates \\"works\\" from \\"scales\\"."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## Big-O in plain words\\nBig-O describes how the work grows with the input size `n`, ignoring constants.\\n\\n| Complexity | n = 1,000 | typical example |\\n|---|---|---|\\n| O(1) | 1 | hash lookup, array index |\\n| O(log n) | 10 | binary search |\\n| O(n) | 1,000 | one pass |\\n| O(n log n) | 10,000 | sorting |\\n| O(n^2) | 1,000,000 | nested loops |\\n| O(2^n) | huge | all subsets |\\n\\nA rough rule: a computer does about 10^8 simple operations per second, so for n = 10^5 aim for O(n log n); for n = 10^3 O(n^2) is fine.\\n\\n## Reading constraints as hints\\n- n <= 20 -> exponential (backtracking, bitmask).\\n- n <= 10^3 -> O(n^2) (simple DP).\\n- n <= 10^5 -> O(n log n) or O(n) (sorting, heap, hash map, two pointers, binary search).\\n- n <= 10^9 -> O(log n) or O(1) (math, binary search on the answer).\\n\\n## Space matters too\\nRecursion uses stack space proportional to its depth; a DP table uses its size. Say both time and space when you explain a solution.\\n\\n## A routine for any problem\\n1. Restate it with a small example.\\n2. Write the brute force and its cost.\\n3. Find the repeated work or the structure to exploit.\\n4. Choose the pattern (hash, window, pointers, binary search, DP, graph...).\\n5. Test on edge cases: empty, one element, duplicates, negatives, the largest input.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Check your understanding', E'{"quiz_questions": [{"question": "For n = 100,000, which time complexity is comfortable?", "options": ["O(n log n)", "O(n^2)", "O(2^n)", "O(n!)"], "correctAnswer": "O(n log n)", "explanation": "n^2 would be 10^10 operations; n log n is about 1.7 million."}, {"question": "A constraint of n <= 20 usually suggests…", "options": ["An exponential solution such as backtracking", "Binary search", "A sieve", "A single pass only"], "correctAnswer": "An exponential solution such as backtracking", "explanation": "2^20 is about a million, which is fine."}, {"question": "What is the first step of the problem-solving routine?", "options": ["Restate the problem with a small example", "Write the optimised code", "Pick a language feature", "Submit"], "correctAnswer": "Restate the problem with a small example", "explanation": "Understanding the problem on a small case prevents solving the wrong thing."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Practice', E'{"task_prompt": "Open Practice and solve these problems, which all use this pattern: Find All Duplicates; Move Zeroes to the End; Missing Number. Write down, in one sentence, why the pattern fits each one."}'::jsonb);
  insert into public.courses (title, slug, description, type, difficulty_level, is_premium, is_published, item_count)
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "A phone costs Rs 20,000 and is \\"20% off, then 10% off\\". Is that 30% off? Seeing why not is the heart of percentages."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## The core idea\\n\\"Percent\\" means \\"per hundred\\". **x% of y = x/100 x y.**\\n\\nConvert freely between the three forms: 25% = 25/100 = 0.25 = 1/4. Knowing the common ones by heart saves minutes:\\n\\n| % | fraction | | % | fraction |\\n|---|---|---|---|---|\\n| 50 | 1/2 | | 12.5 | 1/8 |\\n| 25 | 1/4 | | 20 | 1/5 |\\n| 33.33 | 1/3 | | 10 | 1/10 |\\n| 66.67 | 2/3 | | 5 | 1/20 |\\n\\n## Percentage change\\n**Change % = (new - old) / old x 100.** Always divide by the **old** value.\\n\\n## Successive changes\\nAn increase of a% followed by a change of b% gives a net change of **a + b + ab/100** (use a negative number for a decrease).\\n\\n> Worked example: price up 20% then down 20%. Net = 20 - 20 - (20 x 20)/100 = **-4%**. Going up and down by the same percentage never gets you back to the start.\\n\\n## Population and growth\\nGrowing r% a year for n years multiplies by (1 + r/100)^n.\\n\\n> Worked example: 40,000 growing 10% a year for 2 years = 40,000 x 1.1 x 1.1 = **48,400**.\\n\\n## Quick method for \\"x% of y\\"\\nCompute 10% (move the decimal), then build: 15% = 10% + half of 10%. Example: 15% of 240 = 24 + 12 = **36**.\\n\\n## Common traps\\n- Confusing \\"20% more than\\" (x 1.2) with \\"20% of\\" (x 0.2).\\n- Adding successive percentages instead of using the combined formula.\\n- Dividing by the new value rather than the old one when finding percentage change.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Practice quiz', E'{"quiz_questions": [{"question": "The population of a town is 20,000. It grows by 20% every year. What will it be after 2 years?", "options": ["29,800", "27,800", "28,000", "28,800"], "correctAnswer": "28,800", "explanation": "20,000 x 120/100 x 120/100 = 28,800."}, {"question": "The price of an item is increased by 25% and then decreased by 20%. What is the net change in price? (Positive = increase, negative = decrease.)", "options": ["0%", "5%", "-3%", "2%"], "correctAnswer": "0%", "explanation": "Net change = 25 - 20 - (25 x 20)/100 = 0%."}, {"question": "What is 60% of 360?", "options": ["300", "237", "153", "216"], "correctAnswer": "216", "explanation": "60% of 360 = 60/100 x 360 = 216."}, {"question": "What is 10% of 600?", "options": ["66", "84", "54", "60"], "correctAnswer": "60", "explanation": "10% of 600 = 10/100 x 600 = 60."}, {"question": "The population of a town is 40,000. It grows by 20% every year. What will it be after 2 years?", "options": ["57,600", "59,600", "56,000", "55,600"], "correctAnswer": "57,600", "explanation": "40,000 x 120/100 x 120/100 = 57,600."}, {"question": "The price of an item is increased by 50% and then decreased by 40%. What is the net change in price? (Positive = increase, negative = decrease.)", "options": ["-10%", "10%", "-8%", "-13%"], "correctAnswer": "-10%", "explanation": "Net change = 50 - 40 - (50 x 40)/100 = -10%."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Take it further', E'{"task_prompt": "Make up two questions of your own on this topic, solve them, and swap with a friend. Then try the matching section of a Placement Aptitude mock test."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "A shopkeeper marks a shirt up by 40% and then offers 20% off. Does he gain, break even, or lose?"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## Definitions\\n- **Cost price (CP)**: what the seller paid. **Selling price (SP)**: what the buyer pays.\\n- **Profit = SP - CP**, **Loss = CP - SP**.\\n- **Profit % = profit / CP x 100**, **Loss % = loss / CP x 100**. Both are on the **cost price**.\\n\\n## Direct formulas\\n- SP = CP x (100 + profit%) / 100\\n- SP = CP x (100 - loss%) / 100\\n- CP = SP x 100 / (100 + profit%)  (or 100 - loss%)\\n\\n> Worked example: CP = Rs 1,200, profit 15%. SP = 1,200 x 115/100 = **Rs 1,380**.\\n\\n## Marked price and discount\\n- **Discount is on the marked price (MP)**: SP = MP x (100 - d)/100.\\n- Two successive discounts of d1% and d2% are **not** d1 + d2: multiply the factors.\\n\\n> Worked example: MP = Rs 1,000, discounts 20% and 10%: 1,000 x 0.8 x 0.9 = **Rs 720**, an overall discount of 28%, not 30%.\\n\\n## Marking up then discounting\\nMarked 40% above cost and sold at 20% off: SP = CP x 1.4 x 0.8 = 1.12 CP, a **12% profit**.\\n\\n## Shortcut\\nIf two articles are sold at the same price, one at x% profit and one at x% loss, the overall result is always a **loss of x^2/100 %**.\\n\\n## Common traps\\n- Computing profit % on the selling price.\\n- Applying the second discount to the original marked price instead of the already reduced price.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Practice quiz', E'{"quiz_questions": [{"question": "A shopkeeper buys an article for Rs 4,000 and sells it at a profit of 40%. What is the selling price?", "options": ["Rs 5,200", "Rs 6,000", "Rs 5,600", "Rs 4,040"], "correctAnswer": "Rs 5,600", "explanation": "SP = CP x (100 + 40)/100 = 4000 x 140/100 = 5600."}, {"question": "An article is sold for Rs 900 at a loss of 20%. What was its cost price?", "options": ["Rs 1,225", "Rs 1,080", "Rs 1,025", "Rs 1,125"], "correctAnswer": "Rs 1,125", "explanation": "SP = 80% of CP, so CP = 900 x 100/80 = 1125."}, {"question": "The marked price of a jacket is Rs 1,500. Two successive discounts of 20% and 10% are given. What is the final price?", "options": ["Rs 1,030", "Rs 1,050", "Rs 1,130", "Rs 1,080"], "correctAnswer": "Rs 1,080", "explanation": "Price = 1500 x 80/100 x 90/100 = 1080. (Not 30% off: discounts apply one after the other.)"}, {"question": "A shopkeeper buys an article for Rs 2,000 and sells it at a profit of 15%. What is the selling price?", "options": ["Rs 2,015", "Rs 2,300", "Rs 2,100", "Rs 2,500"], "correctAnswer": "Rs 2,300", "explanation": "SP = CP x (100 + 15)/100 = 2000 x 115/100 = 2300."}, {"question": "An article is sold for Rs 3,600 at a loss of 25%. What was its cost price?", "options": ["Rs 4,700", "Rs 4,900", "Rs 4,800", "Rs 4,500"], "correctAnswer": "Rs 4,800", "explanation": "SP = 75% of CP, so CP = 3600 x 100/75 = 4800."}, {"question": "An article is sold for Rs 2,160 at a loss of 10%. What was its cost price?", "options": ["Rs 2,300", "Rs 2,376", "Rs 2,500", "Rs 2,400"], "correctAnswer": "Rs 2,400", "explanation": "SP = 90% of CP, so CP = 2160 x 100/90 = 2400."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Take it further', E'{"task_prompt": "Make up two questions of your own on this topic, solve them, and swap with a friend. Then try the matching section of a Placement Aptitude mock test."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "Two banks both offer 10%. One pays interest on your original deposit only; the other pays interest on the interest too. After 10 years the gap is large."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## Simple interest (SI)\\n**SI = P x R x T / 100**, and the total amount is P + SI. Interest is always on the original principal.\\n\\n> Worked example: P = 5,000, R = 8%, T = 3 years -> SI = 5,000 x 8 x 3 / 100 = **Rs 1,200**.\\n\\n## Compound interest (CI)\\nInterest is added to the principal each period. **Amount = P x (1 + R/100)^T**, and **CI = Amount - P**.\\n\\n> Worked example: P = 10,000, R = 10%, T = 2 -> Amount = 10,000 x 1.1^2 = 12,100; CI = **Rs 2,100**. The SI would have been Rs 2,000; the extra Rs 100 is interest on interest.\\n\\n## Handy results\\n- For 2 years, CI - SI = P x (R/100)^2.\\n- Half-yearly compounding: use rate R/2 and 2T periods. Quarterly: R/4 and 4T.\\n- Doubling time (rule of 72): at R% compound interest, money doubles in about 72/R years.\\n\\n## Quick multipliers for 2 years\\n10% -> 1.21, 20% -> 1.44, 5% -> 1.1025.\\n\\n## Common traps\\n- Using the simple-interest formula when the problem says \\"compounded\\".\\n- Forgetting to subtract the principal when asked for the interest rather than the amount.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Practice quiz', E'{"quiz_questions": [{"question": "What is the compound interest on Rs 5,000 for 2 years at 10% per annum, compounded yearly?", "options": ["Rs 950", "Rs 1,150", "Rs 1,050", "Rs 1,000"], "correctAnswer": "Rs 1,050", "explanation": "Amount = 5000 x (110/100)^2 = 6050. CI = 6050 - 5000 = 1050."}, {"question": "Find the simple interest on Rs 5,000 at 8% per annum for 3 years.", "options": ["Rs 2,400", "Rs 1,200", "Rs 1,450", "Rs 950"], "correctAnswer": "Rs 1,200", "explanation": "SI = P x R x T / 100 = 5000 x 8 x 3 / 100 = 1200."}, {"question": "Find the simple interest on Rs 2,000 at 6% per annum for 2 years.", "options": ["Rs 340", "Rs 480", "Rs 240", "Rs 140"], "correctAnswer": "Rs 240", "explanation": "SI = P x R x T / 100 = 2000 x 6 x 2 / 100 = 240."}, {"question": "What is the compound interest on Rs 1,000 for 2 years at 20% per annum, compounded yearly?", "options": ["Rs 420", "Rs 460", "Rs 400", "Rs 440"], "correctAnswer": "Rs 440", "explanation": "Amount = 1000 x (120/100)^2 = 1440. CI = 1440 - 1000 = 440."}, {"question": "Find the simple interest on Rs 10,000 at 8% per annum for 4 years.", "options": ["Rs 3,200", "Rs 2,700", "Rs 3,700", "Rs 6,400"], "correctAnswer": "Rs 3,200", "explanation": "SI = P x R x T / 100 = 10000 x 8 x 4 / 100 = 3200."}, {"question": "Find the simple interest on Rs 6,000 at 6% per annum for 2 years.", "options": ["Rs 420", "Rs 1,440", "Rs 1,020", "Rs 720"], "correctAnswer": "Rs 720", "explanation": "SI = P x R x T / 100 = 6000 x 6 x 2 / 100 = 720."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Take it further', E'{"task_prompt": "Make up two questions of your own on this topic, solve them, and swap with a friend. Then try the matching section of a Placement Aptitude mock test."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "A recipe says 3 parts flour to 2 parts sugar. You have 500 g of mix: how much sugar? Ratios turn a story into division."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## Ratios\\na:b means \\"a parts for every b parts\\". To share an amount in a ratio a:b:c, one part = amount / (a + b + c).\\n\\n> Worked example: Rs 6,000 split 2:3:5 -> one part = 6,000/10 = 600, so the shares are **Rs 1,200, Rs 1,800, Rs 3,000**.\\n\\n## Proportion\\nIf a:b = c:d then a x d = b x c (\\"product of extremes = product of means\\"). Direct proportion: more of one gives more of the other. Inverse proportion: more workers, fewer days (workers x days is constant).\\n\\n## Mixtures\\nIn a mixture of milk and water in ratio a:b, milk is a/(a+b) of the whole.\\n\\n> Worked example: 50 L of milk and water in ratio 3:2. Milk = 30 L, water = 20 L. To make the ratio 3:3, water must be 30 L, so add **10 L** of water. (Milk stays at 30 L; only the water changes.)\\n\\n## Alligation (mixing two prices)\\nTo mix two items of price p1 < p2 to get a mean price m, the quantities are in the ratio **(p2 - m) : (m - p1)**.\\n\\n> Worked example: tea at Rs 100 and Rs 200 a kg to make a Rs 140 mix: ratio = (200-140):(140-100) = 60:40 = **3:2**.\\n\\n## Common traps\\n- Treating a ratio as an amount (3:2 is parts, not 3 and 2 units).\\n- Forgetting that the *unchanged* part of a mixture is the anchor when you add something.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Practice quiz', E'{"quiz_questions": [{"question": "Rs 720 is divided among A, B and C in the ratio 1:2:3. How much does A get?", "options": ["Rs 120", "Rs 360", "Rs 240", "Rs 0"], "correctAnswer": "Rs 120", "explanation": "One part = 720/6 = 120. A gets 1 parts = 120."}, {"question": "Rs 600 is divided among A, B and C in the ratio 2:5:3. How much does B get?", "options": ["Rs 420", "Rs 300", "Rs 240", "Rs 360"], "correctAnswer": "Rs 300", "explanation": "One part = 600/10 = 60. B gets 5 parts = 300."}, {"question": "A 60-litre mixture contains milk and water in the ratio 2:1. How many litres of water must be added to make the ratio of milk to water 2:5?", "options": ["90 litres", "80 litres", "75 litres", "85 litres"], "correctAnswer": "80 litres", "explanation": "Milk = 40 L, water = 20 L. For 2:5, water must be 40 x 5/2 = 100 L, so add 80 L."}, {"question": "A 80-litre mixture contains milk and water in the ratio 3:1. How many litres of water must be added to make the ratio of milk to water 3:7?", "options": ["115 litres", "130 litres", "125 litres", "120 litres"], "correctAnswer": "120 litres", "explanation": "Milk = 60 L, water = 20 L. For 3:7, water must be 60 x 7/3 = 140 L, so add 120 L."}, {"question": "Rs 900 is divided among A, B and C in the ratio 1:2:3. How much does C get?", "options": ["Rs 450", "Rs 750", "Rs 300", "Rs 600"], "correctAnswer": "Rs 450", "explanation": "One part = 900/6 = 150. C gets 3 parts = 450."}, {"question": "Rs 720 is divided among A, B and C in the ratio 3:4:5. How much does B get?", "options": ["Rs 240", "Rs 300", "Rs 180", "Rs 360"], "correctAnswer": "Rs 240", "explanation": "One part = 720/12 = 60. B gets 4 parts = 240."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Take it further', E'{"task_prompt": "Make up two questions of your own on this topic, solve them, and swap with a friend. Then try the matching section of a Placement Aptitude mock test."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "One painter takes 12 days, another 24. Together? Not 18 — rates add, not days."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## The core idea\\nThink in **rates**. If A finishes a job in x days, A does **1/x of the job per day**. Rates of people working together add up.\\n\\n**Together: time = xy / (x + y)** for two people.\\n\\n> Worked example: A takes 12 days, B takes 24 days. Together: 12 x 24 / 36 = **8 days**.\\n\\n## Work done and work left\\nIf A works d days of an x-day job, the fraction done is d/x and the fraction left is 1 - d/x.\\n\\n## Pipes and cisterns\\nSame idea: a filling pipe is positive work, an emptying pipe is negative. Net rate = fill rate - empty rate.\\n\\n> Worked example: a tap fills a tank in 6 h, a leak empties it in 12 h. Net = 1/6 - 1/12 = 1/12 per hour, so it fills in **12 hours**.\\n\\n## Workers and days (man-days)\\n**Total work = workers x days x hours.** If the work is fixed: workers1 x days1 = workers2 x days2. 8 workers need 15 days -> 12 workers need 8 x 15/12 = **10 days**.\\n\\n## Efficiency view\\nIf A is twice as efficient as B, A takes half the time. If together they finish in 12 days and A is twice as fast, then B alone takes 36 days and A alone takes 18 days (rates 1/18 + 1/36 = 1/12).\\n\\n## Common traps\\n- Averaging the days (12 and 24 does not give 18).\\n- Forgetting that a worker who leaves early still contributed the part he did.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Practice quiz', E'{"quiz_questions": [{"question": "A can complete a job in 6 days and B can complete it in 3 days. Working together, in how many days will they finish it?", "options": ["3 days", "4 days", "2 days", "1 days"], "correctAnswer": "2 days", "explanation": "Rates add: 1/6 + 1/3 = 9/18 per day, so the job takes 18/9 = 2 days."}, {"question": "A can complete a job in 15 days and B can complete it in 30 days. Working together, in how many days will they finish it?", "options": ["9 days", "12 days", "11 days", "10 days"], "correctAnswer": "10 days", "explanation": "Rates add: 1/15 + 1/30 = 45/450 per day, so the job takes 450/45 = 10 days."}, {"question": "A can complete a job in 9 days and B can complete it in 18 days. Working together, in how many days will they finish it?", "options": ["7 days", "5 days", "6 days", "8 days"], "correctAnswer": "6 days", "explanation": "Rates add: 1/9 + 1/18 = 27/162 per day, so the job takes 162/27 = 6 days."}, {"question": "A worker can finish a task alone in 12 days. After working for 2 days, he leaves. A second worker, who is equally fast, finishes the rest. How many more days does the second worker need?", "options": ["2 days", "12 days", "10 days", "9 days"], "correctAnswer": "10 days", "explanation": "In 2 days 2/12 of the work is done; the rest (10/12) needs 10 days at the same pace."}, {"question": "A worker can finish a task alone in 20 days. After working for 5 days, he leaves. A second worker, who is equally fast, finishes the rest. How many more days does the second worker need?", "options": ["17 days", "5 days", "14 days", "15 days"], "correctAnswer": "15 days", "explanation": "In 5 days 5/20 of the work is done; the rest (15/20) needs 15 days at the same pace."}, {"question": "A worker can finish a task alone in 20 days. After working for 3 days, he leaves. A second worker, who is equally fast, finishes the rest. How many more days does the second worker need?", "options": ["3 days", "17 days", "16 days", "19 days"], "correctAnswer": "17 days", "explanation": "In 3 days 3/20 of the work is done; the rest (17/20) needs 17 days at the same pace."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Take it further', E'{"task_prompt": "Make up two questions of your own on this topic, solve them, and swap with a friend. Then try the matching section of a Placement Aptitude mock test."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "A train enters a tunnel — how long until the last coach leaves? The trick is to ask what distance the train must actually cover."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## The triangle\\n**Distance = Speed x Time.** Keep units consistent.\\n\\nConvert km/h to m/s by multiplying by 5/18; m/s to km/h by 18/5. (54 km/h = 15 m/s.)\\n\\n## Average speed\\nFor the **same distance** at speeds a and b: average = **2ab/(a + b)**, not (a + b)/2.\\n\\n> Worked example: 60 km/h one way and 40 km/h back -> 2 x 60 x 40 / 100 = **48 km/h**.\\n\\n## Relative speed\\n- Towards each other: speeds **add**. Same direction: speeds **subtract**.\\n\\n> Worked example: cities 300 km apart, cars at 40 and 60 km/h start towards each other. Time = 300 / 100 = **3 hours**.\\n\\n## Trains\\n- Crossing a pole or person: distance = train length.\\n- Crossing a platform/bridge: distance = train length + platform length.\\n- Two trains crossing: relative speed, and distance = sum of lengths.\\n\\n> Worked example: a 150 m train at 54 km/h (15 m/s) crosses a 150 m platform in (150 + 150)/15 = **20 s**.\\n\\n## Boats and streams\\nDownstream speed = u + v, upstream = u - v (u = boat in still water, v = stream). Still-water speed = (down + up)/2; stream speed = (down - up)/2.\\n\\n## Common traps\\n- Forgetting the platform''s length for trains.\\n- Using the arithmetic mean for average speed over equal distances.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Practice quiz', E'{"quiz_questions": [{"question": "Two cities are 450 km apart. Two cars start towards each other at the same time from the two cities at 30 km/h and 45 km/h. After how long do they meet?", "options": ["5.5 hours", "30 hours", "6 hours", "6.5 hours"], "correctAnswer": "6 hours", "explanation": "They close the gap at 30 + 45 = 75 km/h, so time = 450/75 = 6 hours."}, {"question": "Two cities are 500 km apart. Two cars start towards each other at the same time from the two cities at 45 km/h and 55 km/h. After how long do they meet?", "options": ["5.5 hours", "5 hours", "50 hours", "4.5 hours"], "correctAnswer": "5 hours", "explanation": "They close the gap at 45 + 55 = 100 km/h, so time = 500/100 = 5 hours."}, {"question": "A boat goes 18 km/h in still water and the stream flows at 6 km/h. How long does it take to go 48 km downstream and come back?", "options": ["5.33333 hours", "5.5 hours", "7 hours", "6 hours"], "correctAnswer": "6 hours", "explanation": "Downstream speed 24, upstream speed 12. Time = 48/24 + 48/12 = 6 hours."}, {"question": "A boat goes 15 km/h in still water and the stream flows at 5 km/h. How long does it take to go 20 km downstream and come back?", "options": ["2.66667 hours", "3 hours", "4 hours", "2.5 hours"], "correctAnswer": "3 hours", "explanation": "Downstream speed 20, upstream speed 10. Time = 20/20 + 20/10 = 3 hours."}, {"question": "Two cities are 600 km apart. Two cars start towards each other at the same time from the two cities at 60 km/h and 90 km/h. After how long do they meet?", "options": ["3.5 hours", "4.5 hours", "20 hours", "4 hours"], "correctAnswer": "4 hours", "explanation": "They close the gap at 60 + 90 = 150 km/h, so time = 600/150 = 4 hours."}, {"question": "A boat goes 14 km/h in still water and the stream flows at 2 km/h. How long does it take to go 48 km downstream and come back?", "options": ["6.85714 hours", "7 hours", "6.5 hours", "8 hours"], "correctAnswer": "7 hours", "explanation": "Downstream speed 16, upstream speed 12. Time = 48/16 + 48/12 = 7 hours."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Take it further', E'{"task_prompt": "Make up two questions of your own on this topic, solve them, and swap with a friend. Then try the matching section of a Placement Aptitude mock test."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "Your marks in five tests average 70. What do you need in the sixth to reach 75? Averages are sums in disguise."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## Averages\\n**Average = sum / count**, so **sum = average x count**. Almost every average problem is solved by switching to sums.\\n\\n> Worked example: average of 5 numbers is 30 and four of them add to 110. The fifth = 30 x 5 - 110 = **40**.\\n\\n## Changing an average\\nWhen a new value joins a group of n with average A, the new average = (n x A + new)/(n + 1).\\n\\n> Worked example: 10 students average 20 years; a 31-year-old teacher joins. New average = (200 + 31)/11 = **21** years.\\n\\n## Weighted average\\nWhen groups have different sizes, weight each average by its size: (n1 A1 + n2 A2)/(n1 + n2).\\n\\n## Ages\\n- Write present ages with one variable (x and x + d).\\n- \\"After n years\\" adds n to **each** person.\\n- The difference between two people''s ages never changes.\\n\\n> Worked example: a father is 4 times his son''s age; the son is 15. In 4 years the father is 4 x 15 + 4 = **64**.\\n\\n## Common traps\\n- Adding n years to only one person.\\n- Averaging two averages without weighting by group size.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Practice quiz', E'{"quiz_questions": [{"question": "The average age of 5 students is 35 years. A teacher aged 71 joins them. What is the new average age?", "options": ["45", "44", "40", "41"], "correctAnswer": "41", "explanation": "Total = 175 + 71 = 246. New average = 246/6 = 41."}, {"question": "The average of 5 numbers is 44. Four of them are 28, 30, 20, 16. What is the remaining number?", "options": ["120", "117", "126", "132"], "correctAnswer": "126", "explanation": "Total = 44 x 5 = 220. Remaining = 220 - 94 = 126."}, {"question": "The sum of the ages of Asha and Bina is 28 years, and Asha is 4 years older than Bina. How old is Asha?", "options": ["16 years", "14 years", "18 years", "13 years"], "correctAnswer": "16 years", "explanation": "Asha = (sum + difference)/2 = (28 + 4)/2 = 16."}, {"question": "The average age of 10 students is 40 years. A teacher aged 73 joins them. What is the new average age?", "options": ["43", "40", "47", "46"], "correctAnswer": "43", "explanation": "Total = 400 + 73 = 473. New average = 473/11 = 43."}, {"question": "A father is 3 times as old as his son, who is 11 years old now. How old will the father be after 6 years?", "options": ["41 years", "50 years", "39 years", "33 years"], "correctAnswer": "39 years", "explanation": "Father now = 3 x 11 = 33. After 6 years: 33 + 6 = 39."}, {"question": "A father is 4 times as old as his son, who is 11 years old now. How old will the father be after 6 years?", "options": ["52 years", "61 years", "44 years", "50 years"], "correctAnswer": "50 years", "explanation": "Father now = 4 x 11 = 44. After 6 years: 44 + 6 = 50."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Take it further', E'{"task_prompt": "Make up two questions of your own on this topic, solve them, and swap with a friend. Then try the matching section of a Placement Aptitude mock test."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "Two buses leave a stop every 12 and 18 minutes. When do they leave together again? The least common multiple answers it."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## HCF and LCM\\n- **HCF (GCD)**: the largest number dividing both. **LCM**: the smallest number both divide.\\n- For two numbers: **HCF x LCM = product of the numbers**.\\n- Use prime factorisation: HCF takes the **smallest** power of each prime, LCM the **largest**.\\n\\n> Worked example: 12 = 2^2 x 3 and 18 = 2 x 3^2. HCF = 2 x 3 = **6**; LCM = 2^2 x 3^2 = **36**. Check: 6 x 36 = 216 = 12 x 18.\\n\\n## Word-problem forms\\n- \\"Meet again after\\" or \\"ring together\\" -> LCM.\\n- \\"Largest equal groups / longest tile that fits\\" -> HCF.\\n\\n## Divisibility rules\\n2: last digit even. 3: digit sum divisible by 3. 4: last two digits. 5: ends in 0 or 5. 9: digit sum divisible by 9. 11: alternating digit sum divisible by 11.\\n\\n## Remainders\\n(a + b) mod m = ((a mod m) + (b mod m)) mod m, and the same for products. For powers, find the repeating cycle of remainders.\\n\\n> Worked example: last digit of 7^k cycles 7, 9, 3, 1. 7^10: 10 mod 4 = 2, so the last digit is **9**; and 2^10 mod 5 = **4**.\\n\\n## Common traps\\n- Mixing up when to use LCM (meeting again) and HCF (splitting equally).\\n- Computing huge powers directly instead of using cycles.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Practice quiz', E'{"quiz_questions": [{"question": "What is the smallest number that is exactly divisible by 12, 8 and 14?", "options": ["168", "126", "210", "189"], "correctAnswer": "168", "explanation": "The answer is LCM(12, 8, 14) = 168."}, {"question": "What is the smallest number that is exactly divisible by 9, 14 and 20?", "options": ["1417", "1731", "946", "1260"], "correctAnswer": "1260", "explanation": "The answer is LCM(9, 14, 20) = 1260."}, {"question": "What is the smallest number that is exactly divisible by 18, 4 and 20?", "options": ["180", "136", "114", "246"], "correctAnswer": "180", "explanation": "The answer is LCM(18, 4, 20) = 180."}, {"question": "Find the HCF (greatest common divisor) of 35 and 63.", "options": ["14", "21", "8", "7"], "correctAnswer": "7", "explanation": "Common prime factors give HCF(35, 63) = 7."}, {"question": "Find the HCF (greatest common divisor) of 8 and 44.", "options": ["3", "12", "4", "8"], "correctAnswer": "4", "explanation": "Common prime factors give HCF(8, 44) = 4."}, {"question": "Find the HCF (greatest common divisor) of 28 and 56.", "options": ["56", "28", "84", "27"], "correctAnswer": "28", "explanation": "Common prime factors give HCF(28, 56) = 28."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Take it further', E'{"task_prompt": "Make up two questions of your own on this topic, solve them, and swap with a friend. Then try the matching section of a Placement Aptitude mock test."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "How many different 4-person committees can a class of 10 form? Counting methodically beats listing."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## Counting rules\\n- **Multiplication rule**: independent stages multiply (3 shirts x 4 trousers = 12 outfits).\\n- **Addition rule**: mutually exclusive choices add.\\n\\n## Permutations (order matters)\\nn! = n x (n-1) x ... x 1. Arranging r of n items: **P(n, r) = n!/(n - r)!**. With repeated letters divide by the factorial of each repeat count.\\n\\n> Worked example: arrangements of LETTER (6 letters, E twice, T twice): 6!/(2! x 2!) = **180**.\\n\\n## Combinations (order does not matter)\\n**C(n, r) = n! / (r! (n - r)!)**, and C(n, r) = C(n, n - r).\\n\\n> Worked example: choosing 4 from 10: C(10, 4) = **210**.\\n\\n## Probability\\n**P(event) = favourable outcomes / total outcomes.** For independent events multiply; for \\"either, not both\\" add.\\n\\n> Worked example: two dice, sum 7: 6 of 36 outcomes -> **1/6**.\\n\\nWithout replacement the second draw changes: 4 red and 3 blue, both red = 4/7 x 3/6 = **2/7**.\\n\\n## Complement trick\\n\\"At least one\\" = 1 - P(none).\\n\\n## Common traps\\n- Using permutations where order does not matter (or the reverse).\\n- Treating draws without replacement as independent.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Practice quiz', E'{"quiz_questions": [{"question": "In how many ways can a committee of 4 people be chosen from 9 people?", "options": ["125", "135", "126", "3024"], "correctAnswer": "126", "explanation": "C(9,4) = 9!/(4! x 5!) = 126."}, {"question": "A bag has 4 red and 3 blue balls. Two balls are drawn one after another without replacement. What is the probability that both are red?", "options": ["16/49", "2/7", "4/7", "12/49"], "correctAnswer": "2/7", "explanation": "P = 4/7 x 3/6 = 2/7."}, {"question": "In how many ways can a committee of 2 people be chosen from 8 people?", "options": ["56", "36", "27", "28"], "correctAnswer": "28", "explanation": "C(8,2) = 8!/(2! x 6!) = 28."}, {"question": "How many distinct arrangements can be made from all the letters of the word APPLE?", "options": ["55", "60", "65", "120"], "correctAnswer": "60", "explanation": "5! divided by the factorials of repeated letters (Px2) = 60."}, {"question": "How many distinct arrangements can be made from all the letters of the word BOOK?", "options": ["8", "24", "12", "16"], "correctAnswer": "12", "explanation": "4! divided by the factorials of repeated letters (Ox2) = 12."}, {"question": "A bag has 5 red and 3 blue balls. Two balls are drawn one after another without replacement. What is the probability that both are red?", "options": ["5/8", "5/16", "5/14", "25/64"], "correctAnswer": "5/14", "explanation": "P = 5/8 x 4/7 = 5/14."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Take it further', E'{"task_prompt": "Make up two questions of your own on this topic, solve them, and swap with a friend. Then try the matching section of a Placement Aptitude mock test."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "The brain loves patterns, and a test setter hides them in numbers and letters. Learn the short list of patterns they reuse."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## Number series: check in this order\\n1. **Constant difference** (arithmetic): 4, 7, 10, 13 -> +3.\\n2. **Constant ratio**: 3, 6, 12, 24 -> x2.\\n3. **Differences that grow**: 1, 2, 4, 7, 11 -> differences 1, 2, 3, 4.\\n4. **Squares / cubes** (maybe plus or minus a constant): 5, 10, 17, 26 -> n^2 + 1.\\n5. **Two interleaved series**: 5, 40, 8, 37, 11, 34 -> +3 on the odd places, -3 on the even.\\n\\n## Coding-decoding\\nLook for a **uniform letter shift**: if CAT -> DBU, each letter moves one place forward, so DOG -> EPH. Also check reversals, position values (A=1 ... Z=26) and swapped pairs.\\n\\n## Analogies\\nFind the relationship first: 3 : 27 :: 4 : ? -> cube, so **64**.\\n\\n## Odd one out\\nFind the property that three share (perfect squares, primes, vowels) and the one that breaks it.\\n\\n## Alphabet positions\\nA=1, B=2 ... M=13, N=14 ... Z=26. Letter k places right of position p is p + k.\\n\\n## Common traps\\n- Settling on the first pattern that fits two terms; make sure it fits **all** the given terms.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Practice quiz', E'{"quiz_questions": [{"question": "Find the next number: 5, 10, 20, 40, ?", "options": ["80", "82", "75", "60"], "correctAnswer": "80", "explanation": "Each term is multiplied by 2: 40 x 2 = 80."}, {"question": "Find the next number: 15, 24, 33, 42, ?", "options": ["48", "51", "49", "50"], "correctAnswer": "51", "explanation": "The difference is always 9, so the next term is 42 + 9 = 51."}, {"question": "Find the next number: 81, 100, 121, 144, ?", "options": ["171", "177", "173", "169"], "correctAnswer": "169", "explanation": "The terms are (9)^2, (10)^2, … ; next is (13)^2 = 169."}, {"question": "Find the next number: 11, 18, 27, 38, ?", "options": ["51", "53", "57", "59"], "correctAnswer": "51", "explanation": "The terms are (3)^2, (4)^2, … plus 2; next is (7)^2 + 2 = 51."}, {"question": "Find the next number: 8, 15, 24, 35, ?", "options": ["48", "54", "46", "56"], "correctAnswer": "48", "explanation": "The terms are (3)^2, (4)^2, … minus 1; next is (7)^2 - 1 = 48."}, {"question": "Find the next number: 1, 2, 4, 8, ?", "options": ["18", "15", "12", "16"], "correctAnswer": "16", "explanation": "Each term is multiplied by 2: 8 x 2 = 16."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Take it further', E'{"task_prompt": "Make up two questions of your own on this topic, solve them, and swap with a friend. Then try the matching section of a Placement Aptitude mock test."}'::jsonb);
