  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "You walk 3 km north and 4 km east. How far are you from home? A right triangle quietly answers a \\"reasoning\\" question."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## Direction sense\\nDraw it. Mark North up, East right. For perpendicular legs a and b the straight-line distance is sqrt(a^2 + b^2): legs 3 and 4 give **5 km**. A right turn is clockwise (N -> E -> S -> W); a left turn is anticlockwise.\\n\\n## Ranking\\nIf a person is p-th from one end and q-th from the other, the line has **p + q - 1** people.\\n\\n> Worked example: 8th from the left and 12th from the right -> 8 + 12 - 1 = **19** people.\\n\\nRank from the bottom = total - rank from the top + 1.\\n\\n## Calendar\\nDays of the week repeat every 7 days, so only the remainder of the day difference mod 7 matters.\\n\\n> Worked example: if today is Wednesday, 100 days later is 100 mod 7 = 2 days ahead -> **Friday**.\\n\\nAn ordinary year has 1 odd day (365 = 52 weeks + 1); a leap year has 2. A year is a leap year if divisible by 4, except century years not divisible by 400.\\n\\n## Clocks\\n- Minute hand: 6 degrees per minute. Hour hand: 0.5 degrees per minute.\\n- Angle at h:m = |30h - 5.5m| (take 360 minus it if larger than 180).\\n\\n> Worked example: at 3:00 -> |90 - 0| = **90 degrees**; at 4:30 -> |120 - 165| = **45 degrees**.\\n\\n## Common traps\\n- Forgetting that the hour hand moves between numbers as the minutes pass.\\n- Mixing up left/right when the person is already facing south or west: always track the facing direction.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Practice quiz', E'{"quiz_questions": [{"question": "In a row of students, Meena is 4th from the left end and 14th from the right end. How many students are in the row?", "options": ["17", "18", "19", "16"], "correctAnswer": "17", "explanation": "Total = 4 + 14 - 1 = 17 (Meena is counted from both ends)."}, {"question": "Arun ranks 25th from the top in a class of 41 students. What is his rank from the bottom?", "options": ["17", "18", "15", "16"], "correctAnswer": "17", "explanation": "Rank from bottom = 41 - 25 + 1 = 17."}, {"question": "In a row of students, Meena is 4th from the left end and 12th from the right end. How many students are in the row?", "options": ["15", "16", "14", "17"], "correctAnswer": "15", "explanation": "Total = 4 + 12 - 1 = 15 (Meena is counted from both ends)."}, {"question": "Ravi walks 5 km south, then turns and walks 12 km west. How far is he from his starting point?", "options": ["14 km", "7 km", "13 km", "17 km"], "correctAnswer": "13 km", "explanation": "The two legs are at right angles, so distance = sqrt(5^2 + 12^2) = 13 km."}, {"question": "A man faces East. He turns right, then left, then right (each a 90-degree turn). Which direction is he facing now?", "options": ["East", "South", "West", "North"], "correctAnswer": "South", "explanation": "Each right turn moves clockwise (N-E-S-W) and each left turn anticlockwise; the end direction is South."}, {"question": "In a row of students, Meena is 20th from the left end and 11th from the right end. How many students are in the row?", "options": ["30", "29", "31", "32"], "correctAnswer": "30", "explanation": "Total = 20 + 11 - 1 = 30 (Meena is counted from both ends)."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Take it further', E'{"task_prompt": "Make up two questions of your own on this topic, solve them, and swap with a friend. Then try the matching section of a Placement Aptitude mock test."}'::jsonb);
  insert into public.chapters (course_id, chapter_number, title, topic_tag, difficulty, story_hook, est_minutes, is_active)
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 1, E'story_hook', E'Story', E'{"story": "Most placement papers have a verbal section where a handful of rules earn most of the marks."}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 2, E'doc', E'Lesson', E'{"doc_md": "## Subject-verb agreement\\n- A singular subject takes a singular verb, whatever comes in between: *The teacher, along with her students, **is** going.*\\n- **Each, every, neither, either, one of** + singular verb: *Each of the players **was** given a medal.*\\n- Collective nouns acting as one take a singular verb: *The committee **has** decided.*\\n\\n## Tenses that tests love\\n- **Present perfect** for an action continuing to now: *She has lived here since 2019.*\\n- **Past perfect** for an action before another past action: *By the time we reached, the train **had left**.*\\n- **Subjunctive / unreal conditional**: *If I **were** you, ...*, *She suggested that he **see** a doctor.*\\n\\n## Prepositions and fixed phrases\\ngood **at**, interested **in**, afraid **of**, depend **on**, look forward **to** + -ing, prefer X **to** Y.\\n\\n## Vocabulary strategy\\n1. Read the sentence and predict the meaning before looking at the options.\\n2. Use word roots: *bene-* (good), *mal-* (bad), *poly-* (many), *anti-* (against).\\n3. For synonyms/antonyms, check whether the question asks for the **opposite**.\\n4. Connectors tell you direction: *although, despite, however* signal contrast; *therefore, so* signal result.\\n\\n## One-word substitutes worth knowing\\npolyglot (many languages), democracy (rule by the people), atheist (does not believe in God), antidote (counteracts poison), etymology (origin of words).\\n\\n## Common spelling traps\\nnecessary, accommodation, occurrence, conscientious, definitely, separate.\\n\\n## Strategy\\nEliminate options that are clearly wrong first; read the full sentence with your chosen answer inserted to check it sounds natural.\\n"}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 3, E'quiz', E'Practice quiz', E'{"quiz_questions": [{"question": "Fill in the blank: There ___ many books on the shelf.", "options": ["was", "has", "are", "is"], "correctAnswer": "are", "explanation": "\\"Books\\" is plural, so \\"there are\\"."}, {"question": "Fill in the blank: By the time we reached the station, the train ___.", "options": ["had left", "left", "was leaving", "has left"], "correctAnswer": "had left", "explanation": "An earlier past action before another past action uses the past perfect."}, {"question": "Fill in the blank: Neither of the two answers ___ correct.", "options": ["were", "are", "is", "be"], "correctAnswer": "is", "explanation": "\\"Neither\\" takes a singular verb."}, {"question": "Choose the word opposite in meaning to GENUINE.", "options": ["Fake", "Honest", "Original", "Real"], "correctAnswer": "Fake", "explanation": "Genuine means real; fake is its opposite."}, {"question": "Choose the word opposite in meaning to FRUGAL.", "options": ["Economical", "Thrifty", "Careful", "Extravagant"], "correctAnswer": "Extravagant", "explanation": "Frugal means careful with money; extravagant means spending lavishly."}, {"question": "What does the idiom \\"a piece of cake\\" mean?", "options": ["Very expensive", "Very small", "Very sweet", "Very easy"], "correctAnswer": "Very easy", "explanation": "It describes something that takes little effort."}]}'::jsonb);
  insert into public.steps (chapter_id, step_number, type, title, content) values (chid, 4, E'task', E'Take it further', E'{"task_prompt": "Make up two questions of your own on this topic, solve them, and swap with a friend. Then try the matching section of a Placement Aptitude mock test."}'::jsonb);
